#ifndef _RLOTTIE_COMMON_H_
#define _RLOTTIE_COMMON_H_

#include <cstdint>
#include <vector>
#if defined _WIN32 || defined __CYGWIN__
  #ifdef RLOTTIE_BUILD
    #define RLOTTIE_API __declspec(dllexport)
  #else
    #define RLOTTIE_API __declspec(dllimport)
  #endif
#else
  #ifdef RLOTTIE_BUILD
      #define RLOTTIE_API __attribute__ ((visibility ("default")))
  #else
      #define RLOTTIE_API
  #endif
#endif


/**
 * @defgroup Lottie_Animation Lottie_Animation
 *
 * Lottie Animation is a modern style vector based animation design. Its animation
 * resource(within json format) could be generated by Adobe After Effect using
 * bodymovin plugin. You can find a good examples in Lottie Community which
 * shares many free resources(see: www.lottiefiles.com).
 *
 * This Lottie_Animation is a common engine to manipulate, control Lottie
 * Animation from the Lottie resource - json file. It provides a scene-graph
 * node tree per frames by user demand as well as rasterized frame images.
 *
 */

/**
 * @ingroup Lottie_Animation
 */

typedef enum
{
    BrushSolid = 0,
    BrushGradient
} LOTBrushType;

typedef enum
{
    FillEvenOdd = 0,
    FillWinding
} LOTFillRule;

typedef enum
{
    JoinMiter = 0,
    JoinBevel,
    JoinRound
} LOTJoinStyle;

typedef enum
{
    CapFlat = 0,
    CapSquare,
    CapRound
} LOTCapStyle;

typedef enum
{
    GradientLinear = 0,
    GradientRadial
} LOTGradientType;

typedef struct LOTGradientStop
{
    float         pos;
    unsigned char r, g, b, a;
} LOTGradientStop;

typedef enum
{
    MaskNone = 0,
    MaskAdd,
    MaskSubstract,
    MaskIntersect,
    MaskDifference
} LOTMaskType;

typedef struct LOTMask {
    struct {
        const float *ptPtr;
        size_t       ptCount;
        const char*  elmPtr;
        size_t       elmCount;
    } mPath;
    LOTMaskType mMode;
    unsigned char mAlpha;
    bool mInv = false;
}LOTMask;

typedef enum
{
    MatteNone = 0,
    MatteAlpha,
    MatteAlphaInv,
    MatteLuma,
    MatteLumaInv
} LOTMatteType;

typedef struct LOTMarker {
   char *name;
   size_t startframe;
   size_t endframe;
} LOTMarker;

typedef struct LOTMarkerList {
   LOTMarker *ptr;
   size_t size;
} LOTMarkerList;

/**
 * effect type 对齐 json文件中的定义type
 */
typedef enum
{
   Effect_Custom = 5, 
   Effect_Displacement = 27, 
   Effect_Drop = 25, 
   Effect_Fill = 21, 
   Effect_Gaussian = 29, 
   Effect_Matte = 28, 
   Effect_Mesh = 31, 
   Effect_Levels = 24, 
   Effect_Puppet = 34, 
   Effect_Radial = 26, 
   Effect_Spherize = 33, 
   Effect_Stroke = 22, 
   Effect_Tint = 20, 
   Effect_Tritone = 23,
   Effect_Twirl = 30, 
   Effect_Wavy = 32
} LOTEffectType;

/**
 * effect Value type 对齐 json文件中的定义type
 */
typedef enum
{
    EFFECT_VALUE_Angle,
    EFFECT_VALUE_Checkbox,
    EFFECT_VALUE_Color,
    EFFECT_VALUE_Drop_Down,
    EFFECT_VALUE_Ignored,
    EFFECT_VALUE_Layer,
    EFFECT_VALUE_Point,
    EFFECT_VALUE_Slider
} LOTEffectValueType;

/**
 * effect Direction
 */
typedef enum
{
    EFFECT_HORIZONTAL = 2,
    EFFECT_VERTICAL = 3,
} LOTEffectDirection;

typedef struct LOTEffect {
    struct EffectValue{
        LOTEffectValueType mEffectValueType;
        bool isAnimated;
        float k;
        std::vector<float> k_array;
    };
    std::vector<EffectValue> mEffectValueArray;
    LOTEffectType mEffectType;
}LOTEffect;



typedef struct LOTNode {

#define ChangeFlagNone 0x0000
#define ChangeFlagPath 0x0001
#define ChangeFlagPaint 0x0010
#define ChangeFlagAll (ChangeFlagPath & ChangeFlagPaint)

    struct {
        const float *ptPtr;
        size_t       ptCount;
        const char  *elmPtr;
        size_t       elmCount;
    } mPath;

    struct {
        unsigned char r, g, b, a;
    } mColor;

    struct {
        unsigned char  enable;
        float       width;
        LOTCapStyle  cap;
        LOTJoinStyle join;
        float       miterLimit;
        float    *dashArray;
        int       dashArraySize;
    } mStroke;

    struct {
        LOTGradientType  type;
        LOTGradientStop *stopPtr;
        size_t           stopCount;
        struct {
            float x, y;
        } start, end, center, focal;
        float cradius;
        float fradius;
    } mGradient;

    struct {
        unsigned char *data;
        size_t width;
        size_t height;
        unsigned char mAlpha;
        struct {
           float m11; float m12; float m13;
           float m21; float m22; float m23;
           float m31; float m32; float m33;
        } mMatrix;
    } mImageInfo;
    
    struct {
        unsigned char isTextNode;
        const char *text;
        const char *fontName;
        float fontSize;
        unsigned char r, g, b, a;
        float x, y;
        struct {
           float m11; float m12; float m13;
           float m21; float m22; float m23;
           float m31; float m32; float m33;
        } mTextMatrix;
        
        unsigned char hasStroke;
        unsigned char sr, sg, sb, sa;
        float strokeWidth;
        float lineHeight;
        float textJustify;
        float tracking;        // 字距调整
        float baselineShift;   // 基线偏移
        float textBoxWidth;    // 文本框宽度
        float textBoxHeight;   // 文本框高度
        float textBoxPosX;     // 文本框X位置
        float textBoxPosY;     // 文本框Y位置
        bool  strokeOverFill;  // 在填充上方渲染描边
        int   caps;            // 字符大小写 (0=正常, 1=大写, 2=小写)
        bool  hasAlignment;    // 是否有对齐信息
        int   textGrouping;    // 文本分组方式 (1=字符,2=单词,3=行,4=全部)
        float alignmentX;      // 对齐锚点X坐标
        float alignmentY;      // 对齐锚点Y坐标

        // 文本范围相关字段
        bool hasTextRange;             // 是否有文本范围
        int textRangeUnit;             // 范围单位：1=百分比，2=索引
        float textRangeStart;          // 范围起始值
        float textRangeEnd;            // 范围结束值
        // rlottie 能力扩展
        float maxEase;
        float minEase;
        float maxAmount;
        int basedOn;                    // 1=Characters, 2=Character Excluding Spaces, 3=Words, 4=Lines
        int randomize;                  // 0-1
        int shape;                      // 1=Square, 2=Ramp Up, 3=Ramp Down, 4=Triangle, 5=Round, 6=Smooth
        float offset;
        float selectorSmoothness;

        // 文本范围样式属性
        bool hasRangeOpacity;
        float rangeOpacity;
        bool hasRangeRotation;
        float rangeRotation;
        bool hasRangeTracking;
        float rangeTracking;
        bool hasRangeStrokeWidth;
        float rangeStrokeWidth;
        bool hasRangePosition;
        float rangePositionX;
        float rangePositionY;
        bool hasRangeScale;
        float rangeScaleX;
        float rangeScaleY;
        bool hasRangeAnchor;
        float rangeAnchorX;
        float rangeAnchorY;
        bool hasRangeFillColor;
        unsigned char rangeFillR, rangeFillG, rangeFillB;
        bool hasRangeStrokeColor;
        unsigned char rangeStrokeR, rangeStrokeG, rangeStrokeB;
        bool hasRangeFillHue;
        float rangeFillHue;
        bool hasRangeFillSaturation;
        float rangeFillSaturation;
        bool hasRangeFillBrightness;
        float rangeFillBrightness;
        // 文本路径属性
        bool  hasTextPath;          // 是否有文本路径
        int   maskIndex;            // 蒙版索引
        float firstMargin;          // 起始边距
        float lastMargin;           // 结束边距
        bool  reversePath;          // 是否反向路径
        bool  forceAlignment;       // 是否强制对齐
        bool  perpendicularToPath;  // 是否垂直于路径
    } mTextInfo;

    int       mFlag;
    LOTBrushType mBrushType;
    LOTFillRule  mFillRule;
    int          mType;

    const char  *keypath;
} LOTNode;



typedef struct LOTLayerNode {

    struct {
        LOTMask        *ptr;
        size_t          size;
    } mMaskList;

    struct {
        const float *ptPtr;
        size_t       ptCount;
        const char  *elmPtr;
        size_t       elmCount;
    } mClipPath;

    struct {
        struct LOTLayerNode   **ptr;
        size_t                  size;
    } mLayerList;

    struct {
        LOTNode        **ptr;
        size_t           size;
    } mNodeList;

    struct {
        LOTEffect       *ptr;
        size_t          size;
    } mEffectList;
    
    LOTMatteType mMatte;
    int          mVisible;
    uint8_t      mAlpha;
    bool         td{false};
    int          tp{0};
    int          mId{-1};
    const char  *keypath;
    bool         mComplexContent{false};
    float        mCombinedAlpha{0.0};

} LOTLayerNode;

/**
 * @}
 */

#endif  // _RLOTTIE_COMMON_H_
